[TFMPageType('Lookup', "Lookup")]
class TFMPageLookupConfiguration extends TFMListPageConfiguration
{
    str					useRegistrationCollector;
    boolean				includeInputDataRowInSubmitRequest;
    boolean				automaticAcceptAfterLastScan;
    TFMAutomaticAccept	automaticAccept;
    boolean				hideAfterAccept;
    boolean				enabled;
    TFMPageID			navigateTo;
    TFMPageID			navigateToOnSuccess;    
    boolean				close;
    boolean				refreshOnSuccess;
    str					lookup;
    str					submit;
    TFMListId			listId;

}

Method.Source:
[TFMPageConfigurationAttributeAttribute('','')]
public str parmType(str _type = type)
{
    type = _type;
    return type;
}

[TFMPageConfigurationAttributeAttribute('Auto','','',false,false)]
public str parmUseRegistrationCollector(str _useRegistrationCollector = useRegistrationCollector)
{
    useRegistrationCollector = _useRegistrationCollector;
    return useRegistrationCollector;
}

[TFMPageConfigurationAttributeAttribute(false,'')]
public boolean parmIncludeInputDataRowInSubmitRequest(boolean _includeInputDataRowInSubmitRequest = includeInputDataRowInSubmitRequest)
{
    includeInputDataRowInSubmitRequest = _includeInputDataRowInSubmitRequest;
    return includeInputDataRowInSubmitRequest;
}

[TFMPageConfigurationAttributeAttribute(true,'header','',true)]
public boolean parmHideAfterAccept(boolean _hideAfterAccept = hideAfterAccept)
{
    hideAfterAccept = _hideAfterAccept;
    return hideAfterAccept;
}

[TFMPageConfigurationAttributeAttribute(true,'header','',true)]
public boolean parmAutomaticAcceptAfterLastScan(boolean _automaticAcceptAfterLastScan = automaticAcceptAfterLastScan)
{
    automaticAcceptAfterLastScan = _automaticAcceptAfterLastScan;
    return automaticAcceptAfterLastScan;
}

[TFMPageConfigurationAttributeAttribute(true,'onResultSelected')]
public boolean parmEnabled(boolean _enabled = enabled)
{
    enabled = _enabled;
    return enabled;
}

[TFMPageConfigurationAttributeAttribute('','onResultSelected')]
public TFMPageID parmNavigateTo(TFMPageID _navigateTo = navigateTo)
{
    navigateTo = _navigateTo;
    return navigateTo;
}

    [TFMPageConfigurationAttributeAttribute(classStr(TFMListLookupWithRegistrations),'list','',true)]
    public TFMListId parmListId(TFMListId _listId = listId)
    {        
        TFMList			listCls;
        listId = _listId;
		if (className2Id(listId))
        {
            listCls = new SysDictClass(className2Id(listId)).makeObject();
            listId = listCls.parmListName();
		}
        return listId;
    }

[TFMPageConfigurationAttributeAttribute(false,'onSuccessfulPost')]
public boolean parmClose(boolean _close = close)
{
    close = _close;
    return close;
}

[TFMPageConfigurationAttributeAttribute('','onSuccessfulPost','navigateTo')]
public TFMPageID parmNavigateToOnSuccess(TFMPageID _navigateToOnSuccess = navigateToOnSuccess)
{
    navigateToOnSuccess = _navigateToOnSuccess;
    return navigateToOnSuccess;
}

[TFMPageConfigurationAttributeAttribute(true,'onSuccessfulPost','',true)]
public boolean parmRefreshOnSuccess(boolean _refreshOnSuccess = refreshOnSuccess)
{
    refreshOnSuccess = _refreshOnSuccess;
    return refreshOnSuccess;
}

[TFMPageConfigurationAttributeAttribute(0,'header')]
public TFMAutomaticAcceptEDT parmAutomaticAccept(TFMAutomaticAcceptEDT _automaticAccept = automaticAccept)
{
    automaticAccept = _automaticAccept;
    return automaticAccept;
}

[TFMPageConfigurationAttributeAttribute('','requests/', 'lookup')]
public str parmLookup(str _lookup = lookup)
{
    lookup = _lookup;
    return lookup;
}

[TFMPageConfigurationAttributeAttribute('','requests/', 'submit')]
public str parmSubmit(str _submit = submit)
{
    submit = _submit;
    return submit;
}
